-- +goose Up
-- Catalog: canonical ingredients, units and equipment with their aliases
-- (ADR-00008, ADR-00005). Names and aliases are stored trimmed and lower-case
-- by the catalog package; the UNIQUE constraints rely on that.
-- unit.factor is the exact number of base units (g, ml, each) in one unit,
-- as text in a form quantity.ParseRat reads. It is NULL for dimension 'other'.
-- ingredients.density_g_per_ml is grams per millilitre and NULL when unknown.

CREATE TABLE units (
    id        INTEGER PRIMARY KEY,
    name      TEXT NOT NULL UNIQUE CHECK (name <> ''),
    system    TEXT NOT NULL CHECK (system IN ('us', 'metric', 'none')),
    dimension TEXT NOT NULL CHECK (dimension IN ('mass', 'volume', 'count', 'other')),
    factor    TEXT CHECK (factor IS NULL OR factor <> ''),
    reviewed  INTEGER NOT NULL DEFAULT 0 CHECK (reviewed IN (0, 1)),
    CHECK ((dimension = 'other' AND factor IS NULL) OR (dimension <> 'other' AND factor IS NOT NULL))
);

CREATE TABLE unit_aliases (
    alias   TEXT PRIMARY KEY CHECK (alias <> ''),
    unit_id INTEGER NOT NULL REFERENCES units (id) ON DELETE CASCADE
);
CREATE INDEX unit_aliases_unit_id ON unit_aliases (unit_id);

CREATE TABLE ingredients (
    id               INTEGER PRIMARY KEY,
    name             TEXT NOT NULL UNIQUE CHECK (name <> ''),
    aisle            TEXT NOT NULL CHECK (aisle <> ''),
    density_g_per_ml REAL CHECK (density_g_per_ml IS NULL OR density_g_per_ml > 0),
    usda_fdc_id      INTEGER UNIQUE CHECK (usda_fdc_id IS NULL OR usda_fdc_id > 0),
    reviewed         INTEGER NOT NULL DEFAULT 0 CHECK (reviewed IN (0, 1))
);

CREATE TABLE ingredient_aliases (
    alias         TEXT PRIMARY KEY CHECK (alias <> ''),
    ingredient_id INTEGER NOT NULL REFERENCES ingredients (id) ON DELETE CASCADE
);
CREATE INDEX ingredient_aliases_ingredient_id ON ingredient_aliases (ingredient_id);

CREATE TABLE equipment (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE CHECK (name <> ''),
    reviewed INTEGER NOT NULL DEFAULT 0 CHECK (reviewed IN (0, 1))
);

CREATE TABLE equipment_aliases (
    alias        TEXT PRIMARY KEY CHECK (alias <> ''),
    equipment_id INTEGER NOT NULL REFERENCES equipment (id) ON DELETE CASCADE
);
CREATE INDEX equipment_aliases_equipment_id ON equipment_aliases (equipment_id);

-- Seed: curated units, ingredients and equipment (internal/catalog/seed).
-- Unit systems, dimensions and factors are quantity's built-in table.




-- +goose Down
DROP TABLE equipment_aliases;
DROP TABLE equipment;
DROP TABLE ingredient_aliases;
DROP TABLE ingredients;
DROP TABLE unit_aliases;
DROP TABLE units;
